<?php
declare(strict_types=1);
// Reuse the disposable localhost fixture; no private .env or hosted records are loaded.
require __DIR__.'/recurring-bookings.php';
use Wellness\Auth\AuthContext;
use Wellness\Http\ApiException;
use Wellness\Service\{AuditLogger,ClientFormsService,ClientService};
$pdo->exec(file_get_contents(dirname(__DIR__,2).'/database/migrations/005_customer_onboarding.sql'));
$pdo->exec(file_get_contents(dirname(__DIR__,2).'/database/migrations/036_client_intake_forms.sql'));
$_ENV['CLIENT_FORMS_ENABLED']='true';$_ENV['CLIENT_FORM_ANSWERS_ENABLED']='true';
$forms=new ClientFormsService($database,new AuditLogger($database));$checks=0;
$assert=function(bool $ok,string $why)use(&$checks){if(!$ok)throw new RuntimeException($why);$checks++;};
$deny=function(callable $fn,string $code)use($assert){try{$fn();}catch(ApiException $e){$assert($e->errorCode===$code,'Expected '.$code.', got '.$e->errorCode);return;}throw new RuntimeException('Expected '.$code);};
$practitioner=new AuthContext(2,1,'','','','staff',['practitioner']);
$otherClient=new AuthContext(9,1,'','','','client',[]);$foreign=new AuthContext(10,2,'','','','client',[]);
$pdo->exec("INSERT INTO users(id,clinic_id,email,display_name,user_type,status) VALUES(11,1,'unrelated@example.test','Unrelated practitioner','staff','active'); INSERT INTO practitioners(id,user_id,discipline,booking_mode) VALUES(12,11,'Massage','practitioner_managed')");
$unrelated=new AuthContext(11,1,'','','','staff',['practitioner']);
$definition=['questions'=>[['id'=>'text','label'=>'Synthetic answer','type'=>'text','required'=>true],['id'=>'yes','label'=>'Synthetic yes/no','type'=>'yes_no','required'=>true],['id'=>'consent','label'=>'Synthetic consent','type'=>'consent','required'=>true]]];
$template=$forms->publish($practitioner,['owner_practitioner_id'=>3,'name'=>'Synthetic answer changes','form_type'=>'consent','definition'=>$definition,'service_ids'=>[],'idempotency_key'=>'answer-change-template'],'answer-test');
$task=$forms->assign($admin,8,['template_id'=>$template['id'],'idempotency_key'=>'answer-change-task'],'answer-test')['id'];
$draft=['version'=>1,'answers'=>['consent'=>false,'text'=>'private draft é'],'idempotency_key'=>'answer-draft-one'];
$deny(fn()=>$forms->saveAnswers($client,$task,$draft,'answer-test'),'answer_changes_disabled');
$assert(!$forms->detail($client,$task,'answer-test')['answer_changes_enabled'],'Missing migration disables capability');
$pdo->exec(file_get_contents(dirname(__DIR__,2).'/database/migrations/041_client_form_answers.sql'));
$saved=$forms->saveAnswers($client,$task,$draft,'answer-test');
$assert($saved['version']===2&&$saved['status']==='pending','Saving advances task revision without submitting');
$assert($forms->saveAnswers($client,$task,$draft,'answer-test')===$saved,'Uncertain save replays same receipt');
$assert((int)$pdo->query('SELECT COUNT(*) FROM form_submissions')->fetchColumn()===0,'Draft creates no submission');
$assert((int)$pdo->query('SELECT COUNT(*) FROM consent_records')->fetchColumn()===0,'Draft creates no consent evidence');
$detail=$forms->detail($client,$task,'answer-test');
$assert($detail['draft']['answers']===$draft['answers'],'Client resumes partial answer draft');
$assert($forms->detail($practitioner,$task,'answer-test')['draft']===null,'Assigned practitioner cannot read client draft');
$deny(fn()=>$forms->detail($admin,$task,'answer-test'),'forbidden');
$deny(fn()=>$forms->saveAnswers($practitioner,$task,$draft,'answer-test'),'forbidden');
$deny(fn()=>$forms->saveAnswers($otherClient,$task,$draft,'answer-test'),'form_not_found');
$deny(fn()=>$forms->saveAnswers($foreign,$task,$draft,'answer-test'),'form_not_found');
$deny(fn()=>$forms->detail($unrelated,$task,'answer-test'),'form_not_found');
$deny(fn()=>$forms->saveAnswers($client,$task,array_replace($draft,['answers'=>['text'=>'different']]),'answer-test'),'idempotency_conflict');
$deny(fn()=>$forms->saveAnswers($client,$task,array_replace($draft,['idempotency_key'=>'stale-tab-save']),'answer-test'),'form_changed');
$deny(fn()=>$forms->submit($client,$task,['version'=>2,'confirmed'=>true,'answers'=>$draft['answers']],'answer-test'),'invalid_form');
$answers=['consent'=>true,'text'=>'original response é','yes'=>false];
$deny(fn()=>$forms->submit($client,$task,['version'=>1,'confirmed'=>true,'answers'=>$answers],'answer-test'),'form_changed');
$forms->submit($client,$task,['version'=>2,'confirmed'=>true,'answers'=>$answers],'answer-test');
$assert((int)$pdo->query('SELECT COUNT(*) FROM client_form_answer_drafts')->fetchColumn()===0,'Final submission removes draft');
$original=$forms->detail($client,$task,'answer-test');$submission=(int)$original['submission_id'];
$originalBytes=$pdo->query('SELECT HEX(response_data) FROM form_submissions WHERE id='.$submission)->fetchColumn();
$forms->transition($practitioner,$task,['action'=>'review','version'=>3],'answer-test');
$oldReview=$pdo->query('SELECT reviewed_at FROM form_submissions WHERE id='.$submission)->fetchColumn();
$amend=['version'=>4,'confirmed'=>true,'answers'=>array_replace($answers,['text'=>'corrected response é']),'reason'=>'Correction privée é','idempotency_key'=>'answer-amend-one'];
$deny(fn()=>$forms->saveAnswers($client,$task,array_replace($amend,['confirmed'=>false]),'answer-test',true),'invalid_form');
$deny(fn()=>$forms->saveAnswers($client,$task,array_replace($amend,['reason'=>'']),'answer-test',true),'invalid_form');
$deny(fn()=>$forms->saveAnswers($client,$task,array_replace($amend,['answers'=>$answers]),'answer-test',true),'invalid_form');
$deny(fn()=>$forms->saveAnswers($client,$task,array_replace($amend,['answers'=>array_replace($amend['answers'],['consent'=>false])]),'answer-test',true),'invalid_form');
$changed=$forms->saveAnswers($client,$task,$amend,'answer-test',true);
$assert($changed['version']===5&&$changed['status']==='submitted','Amendment requests new practitioner review');
$assert($forms->saveAnswers($client,$task,$amend,'answer-test',true)===$changed,'Amendment retry appends only once');
$assert((int)$pdo->query('SELECT COUNT(*) FROM client_form_amendments')->fetchColumn()===1,'Single amendment after retry');
$assert($pdo->query('SELECT HEX(response_data) FROM form_submissions WHERE id='.$submission)->fetchColumn()===$originalBytes,'Original response bytes unchanged');
$assert($pdo->query('SELECT reviewed_at FROM form_submissions WHERE id='.$submission)->fetchColumn()===$oldReview,'Original review evidence retained');
$history=$forms->detail($practitioner,$task,'answer-test');
$assert($history['original_answers']===$answers&&$history['answers']===$amend['answers'],'Practitioner sees original and effective answers');
$assert($history['reviewed_at']===null&&count($history['amendments'])===1,'New amendment is not silently reviewed');
$forms->transition($practitioner,$task,['action'=>'review','version'=>5],'answer-test');
$assert($forms->detail($client,$task,'answer-test')['amendments'][0]['reviewed_at']!==null,'Review records latest amendment');
$second=array_replace($amend,['version'=>6,'answers'=>array_replace($answers,['text'=>'second correction']),'idempotency_key'=>'answer-amend-two']);
$forms->saveAnswers($client,$task,$second,'answer-test',true);
$assert(count($forms->detail($client,$task,'answer-test')['amendments'])===2,'Second correction appends history');
$deny(fn()=>$forms->saveAnswers($client,$task,array_replace($second,['idempotency_key'=>'stale-amendment']),'answer-test',true),'form_changed');
$deny(fn()=>$forms->saveAnswers($client,$task,array_replace($draft,['version'=>7,'idempotency_key'=>'post-submit-draft']),'answer-test'),'form_changed');
$_ENV['CLIENT_FORM_ANSWERS_ENABLED']='false';
$assert(count($forms->detail($client,$task,'answer-test')['amendments'])===2,'Disabling writes retains amendment history');
$deny(fn()=>$forms->saveAnswers($client,$task,$second,'answer-test',true),'answer_changes_disabled');
$_ENV['CLIENT_FORM_ANSWERS_ENABLED']='true';
$pending=$forms->assign($admin,8,['template_id'=>$template['id'],'idempotency_key'=>'answer-pending-merge'],'answer-test')['id'];
$forms->saveAnswers($client,$pending,$draft,'answer-test');
$pdo->setAttribute(PDO::ATTR_STRINGIFY_FETCHES,true);
try{$receipt=$forms->saveAnswers($client,$pending,array_replace($draft,['version'=>2,'idempotency_key'=>'stringified-answer-draft']),'answer-test');$assert($receipt['version']===3,'Save revision remains numeric with stringifying PDO');$assert($forms->saveAnswers($client,$pending,array_replace($draft,['version'=>2,'idempotency_key'=>'stringified-answer-draft']),'answer-test')===$receipt,'Replay keeps numeric receipt');}finally{$pdo->setAttribute(PDO::ATTR_STRINGIFY_FETCHES,false);}
$revoked=$forms->assign($admin,8,['template_id'=>$template['id'],'idempotency_key'=>'answer-revoked'],'answer-test')['id'];
$forms->saveAnswers($client,$revoked,$draft,'answer-test');$forms->transition($admin,$revoked,['action'=>'revoke','version'=>2],'answer-test');
$assert($forms->detail($client,$revoked,'answer-test')['draft']===null,'Revocation clears saved draft');
$deny(fn()=>$forms->saveAnswers($client,$revoked,array_replace($draft,['version'=>3,'idempotency_key'=>'revoked-save']),'answer-test'),'form_changed');
$clients=new ClientService($database,new AuditLogger($database));$preview=$clients->mergePreview($admin,9,8,'answer-test');
$clients->merge($admin,9,8,['survivor_revision'=>$preview['survivor']['revision'],'duplicate_revision'=>$preview['duplicate']['revision'],'reason'=>'Synthetic test only','confirmation'=>'MERGE 8 INTO 9'],'answer-test');
$assert($forms->detail($otherClient,$pending,'answer-test')['draft']['answers']===$draft['answers'],'Draft ownership follows supervised merge');
$assert(count($forms->detail($otherClient,$task,'answer-test')['amendments'])===2,'Correction history follows supervised merge');
$deny(fn()=>$forms->detail($client,$task,'answer-test'),'form_not_found');
$metadata=$pdo->query("SELECT metadata FROM audit_logs WHERE action IN ('form.answer_draft.save','form.amend')")->fetchAll(PDO::FETCH_COLUMN);
$assert(!str_contains(json_encode($metadata),'private draft')&&!str_contains(json_encode($metadata),'Correction'),'Private content excluded from audit metadata');
$pdo->exec('SET character_set_results=latin1');
try{$assert($forms->detail($otherClient,$task,'answer-test')['amendments'][0]['reason']===$amend['reason'],'UTF-8 correction reason preserved despite result charset');}finally{$pdo->exec('SET character_set_results=utf8mb4');}
$assert(!$pdo->inTransaction(),'No leaked transactions');
echo "Client form answers: $checks real SQL assertions passed.\n";
